)

// exportFixture is a minimal but faithful /export document: document view,
// collections inlined, message attributes on the default version — the
// shape the server guarantees for real.
const exportFixture = `{
  "specversion": "1.0-rc2",
  "registryid": "intropy",
  "self": "/",
  "xid": "/",
  "messagegroups": {
    "io.intropy.maxbo.product": {
      "messagegroupid": "io.intropy.maxbo.product",
      "xid": "/messagegroups/io.intropy.maxbo.product",
      "name": "Maxbo product distribution",
      "envelope": "CloudEvents/1.0",
      "protocol": "AMQP/1.0",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
          "name": "Product export completed",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "envelope": "CloudEvents/1.0",
              "envelopemetadata": {
                "type": {"value": "io.intropy.maxbo.product.export", "type": "string", "required": true},
                "subject": {"type": "string", "required": true}
              },
              "protocol": "AMQP/1.0",
              "dataschemaformat": "JsonSchema/draft/2020-12",
              "dataschemaxid": "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
              "datacontenttype": "application/json"
            }
          }
        }
      }
    },
    "io.intropy.acme.orders": {
      "messagegroupid": "io.intropy.acme.orders",
      "xid": "/messagegroups/io.intropy.acme.orders",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.acme.orders/messages/io.intropy.maxbo.product.export",
          "versions": {
            "1": {"versionid": "1", "isdefault": true}
          }
        }
      }
    }
  },
  "schemagroups": {
    "io.intropy.maxbo.product": {
      "schemagroupid": "io.intropy.maxbo.product",
      "xid": "/schemagroups/io.intropy.maxbo.product",
      "schemas": {
        "product-export.v1": {
          "schemaid": "product-export.v1",
          "xid": "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "format": "JsonSchema/draft/2020-12",
              "formatvalidated": true,
              "schema": {"title": "Export Event", "type": "object"}
            }
          }
