      }
    }
  },
  "endpoints": {
    "perfion-extractor": {
      "endpointid": "perfion-extractor",
      "xid": "/endpoints/perfion-extractor",
      "usage": ["producer"],
      "channel": "product-distribution-pubsub/sbt-test-product-extractor-001",
      "envelope": "CloudEvents/1.0",
      "protocol": "AMQP/1.0",
      "messagegroups": ["/messagegroups/io.intropy.maxbo.product"]
    },
    "kat-product-loader": {
      "endpointid": "kat-product-loader",
      "xid": "/endpoints/kat-product-loader",
      "usage": ["subscriber"],
      "channel": "product-distribution-pubsub/sbt-test-product-extractor-001",
      "messagegroups": ["/messagegroups/io.intropy.maxbo.product"]
    }
  }
}`

func exportServer(t *testing.T, handler http.Handler) *Client {
	t.Helper()
	srv := httptest.NewServer(handler)
	t.Cleanup(srv.Close)
	c, err := NewClient(srv.URL + "/")
	if err != nil {
		t.Fatal(err)
	}
	return c
}

func fixtureHandler(status int, body string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write([]byte(body))
	})
}

func TestExportPopulatesModel(t *testing.T) {
	var gotAccept, gotPath string
	c := exportServer(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotAccept = r.Header.Get("Accept")
		gotPath = r.URL.Path
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(exportFixture))
	}))

	doc, err := c.Export(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if gotPath != "/export" {
		t.Errorf("request path = %q, want /export (trailing-slash base must join cleanly)", gotPath)
	}
	if gotAccept != "application/json" {
		t.Errorf("Accept = %q, want application/json", gotAccept)
	}
	if doc.RegistryID != "intropy" {
		t.Errorf("RegistryID = %q", doc.RegistryID)
	}
	g := doc.MessageGroups["io.intropy.maxbo.product"]
	if g == nil {
		t.Fatal("message group missing")
	}
	m := g.Messages["io.intropy.maxbo.product.export"]
	if m == nil {
		t.Fatal("message missing")
	}
	v := m.DefaultVersion()
	if v == nil {
		t.Fatal("no default version")
	}
	if v.DataschemaXid != "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1" {
		t.Errorf("DataschemaXid = %q", v.DataschemaXid)
	}
	// The document view puts message attributes on the version, not the
	// resource — a client reading them off the resource reads nothing.
	if m.MessageID != "io.intropy.maxbo.product.export" {
		t.Errorf("MessageID = %q", m.MessageID)
	}
	s := doc.SchemaGroups["io.intropy.maxbo.product"].Schemas["product-export.v1"].DefaultVersion()
	if s == nil || s.Format != "JsonSchema/draft/2020-12" {
		t.Errorf("schema default version = %+v", s)
	}
	if !strings.Contains(string(s.Document), "Export Event") {
		t.Errorf("schema document = %s", s.Document)
	}
}

func TestExportServerError(t *testing.T) {
	c := exportServer(t, fixtureHandler(http.StatusInternalServerError, "boom"))
	_, err := c.Export(context.Background())
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), "get export") || !strings.Contains(err.Error(), "500") {
		t.Errorf("error should name the operation and status, got %q", err)
	}
}

func TestExportInvalidJSON(t *testing.T) {
	c := exportServer(t, fixtureHandler(http.StatusOK, "{not json"))
	_, err := c.Export(context.Background())
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), "parse") {
		t.Errorf("error should name the parse failure, got %q", err)
	}
}

func TestNewClientRejectsRelativeURL(t *testing.T) {
	if _, err := NewClient("registry.example.com"); err == nil {
		t.Fatal("expected error for non-absolute URL")
	}
}

func fixtureExport(t *testing.T) *Export {
	t.Helper()
	var doc Export
	if err := doc.UnmarshalJSONForTest(exportFixture); err != nil {
		t.Fatal(err)
	}
	return &doc
}

func TestResolveMessageBareID(t *testing.T) {
	// The fixture declares the same message id in two groups, so a bare id
	// is ambiguous; a group-unique id resolves.
	doc := fixtureExport(t)
	doc.MessageGroups["io.intropy.acme.orders"].Messages["io.intropy.acme.orders.placed"] = &Message{
		MessageID: "io.intropy.acme.orders.placed",
		Xid:       "/messagegroups/io.intropy.acme.orders/messages/io.intropy.acme.orders.placed",
		Versions:  map[string]*MessageVersion{"1": {VersionID: "1", IsDefault: true}},
	}

	r, err := doc.ResolveMessage("io.intropy.acme.orders.placed")
	if err != nil {
		t.Fatal(err)
	}
	if r.Group.MessageGroupID != "io.intropy.acme.orders" {
		t.Errorf("group = %q", r.Group.MessageGroupID)
	}
	if r.Version == nil || r.Version.VersionID != "1" {
		t.Errorf("version = %+v", r.Version)
	}
}

func TestResolveMessageAmbiguousBareID(t *testing.T) {
	doc := fixtureExport(t)
	_, err := doc.ResolveMessage("io.intropy.maxbo.product.export")
	var amb *AmbiguousMessageError
	if !errors.As(err, &amb) {
		t.Fatalf("err = %v, want AmbiguousMessageError", err)
	}
	if len(amb.Xids) != 2 {
		t.Errorf("xids = %v", amb.Xids)
	}
	if !strings.Contains(err.Error(), "use a full xid") {
		t.Errorf("error should carry the remediation, got %q", err)
	}
}

func TestResolveMessageXid(t *testing.T) {
	doc := fixtureExport(t)
	r, err := doc.ResolveMessage("/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export")
	if err != nil {
		t.Fatal(err)
	}
	if got := r.CloudEventsType(); got != "io.intropy.maxbo.product.export" {
		t.Errorf("CloudEventsType = %q", got)
	}
}

func TestResolveMessageNotFound(t *testing.T) {
	doc := fixtureExport(t)
	for _, ref := range []string{
		"io.intropy.nope",
		"/messagegroups/io.intropy.nope/messages/io.intropy.nope",
		// A schema xid where a message belongs is "no such message".
		"/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
	} {
		_, err := doc.ResolveMessage(ref)
		var nf *MessageNotFoundError
		if !errors.As(err, &nf) {
			t.Errorf("ResolveMessage(%q) err = %v, want MessageNotFoundError", ref, err)
			continue
		}
		if !strings.Contains(err.Error(), ref) {
			t.Errorf("error should carry the ref, got %q", err)
		}
	}
}

func TestProducerEndpointsFor(t *testing.T) {
	doc := fixtureExport(t)

	eps := doc.ProducerEndpointsFor("io.intropy.maxbo.product")
	if len(eps) != 1 || eps[0].EndpointID != "perfion-extractor" {
		t.Errorf("producers = %v", eps)
	}

	// No producer declared is distinct from the group not existing: both
	// are an empty slice here, and the caller pairs this with a resolved
	// message to tell "no producer" apart from "no such group".
	if eps := doc.ProducerEndpointsFor("io.intropy.acme.orders"); len(eps) != 0 {
		t.Errorf("producers for producer-less group = %v", eps)
	}
}

func TestSplitChannel(t *testing.T) {
	pubsub, topic, err := SplitChannel("product-distribution-pubsub/sbt-test-product-extractor-001")
	if err != nil {
		t.Fatal(err)
	}
	if pubsub != "product-distribution-pubsub" || topic != "sbt-test-product-extractor-001" {
		t.Errorf("got %q / %q", pubsub, topic)
	}
	for _, bad := range []string{"", "nopubsub", "/topic", "pubsub/"} {
		if _, _, err := SplitChannel(bad); err == nil {
			t.Errorf("SplitChannel(%q) should fail", bad)
		}
	}
}

