		t.Fatal(err)
	}
	writeFileT(t, filepath.Join(intropyDir, "scaffold.json"),
		`{"schemaVersion":1,"template":"`+template+`","owner":"integrio-intropy","repo":"intropy-templates","version":"`+version+`","values":{"appId":"int1"}}`+"\n")
}

