	if err := rootCmd.Execute(); err != nil {
		t.Fatalf("execute: %v", err)
	}
	out := stdout.String()
	for _, want := range []string{"PATH", "TEMPLATE", "VERSION", "orders", "hello-world", "v0.1.6", filepath.Join("team", "invoices"), "transactional", "v0.2.0"} {
