// ResolvedSchema is a schema joined with its group and default version.
type ResolvedSchema struct {
	Group   *SchemaGroup
	Schema  *Schema
	Version *SchemaVersion
}

// SchemaNotFoundError reports a dataschema xid no schema in the registry
// matches.
type SchemaNotFoundError struct {
	Xid string
}

func (e *SchemaNotFoundError) Error() string {
	return fmt.Sprintf("schema %q not found in registry", e.Xid)
}

// ResolveSchema resolves a dataschema xid of the form
// /schemagroups/<gid>/schemas/<sid> — the reference a message's
// dataschemaxid carries. A malformed or dangling reference is a
// SchemaNotFoundError, never a panic: the registry keeps unresolved
// references with a warning, so clients meet them in the wild.
func (e *Export) ResolveSchema(xid string) (*ResolvedSchema, error) {
	parts := strings.Split(strings.TrimPrefix(xid, "/"), "/")
	if len(parts) != 4 || parts[0] != "schemagroups" || parts[2] != "schemas" {
		return nil, &SchemaNotFoundError{Xid: xid}
	}
	g, ok := e.SchemaGroups[parts[1]]
	if !ok {
		return nil, &SchemaNotFoundError{Xid: xid}
	}
	s, ok := g.Schemas[parts[3]]
	if !ok {
		return nil, &SchemaNotFoundError{Xid: xid}
	}
	return &ResolvedSchema{Group: g, Schema: s, Version: s.DefaultVersion()}, nil
}

