package template

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// SubscriptionRecord is the committed trace of one message-ref parameter's
// resolution: which registry message the component subscribes to, pinned to
// the schema version that was the registry's default at scaffold time. It
// travels in the scaffold record so later commands can compare what the
// component was scaffolded against with what the registry now declares.
type SubscriptionRecord struct {
	// Parameter is the message-ref template parameter that held the
	// reference.
	Parameter string `json:"parameter"`
	// Message is the message's full xid — unambiguous where a bare message
	// id is not.
	Message string `json:"message"`
	// SchemaID and SchemaVersion come from the schema resource the
	// message's dataschemaxid pointed at. Empty when that reference dangles
	// — the registry keeps unresolved references with a warning, and the
	// record mirrors what the registry actually said.
	SchemaID      string `json:"schemaid,omitempty"`
	SchemaVersion string `json:"schemaVersion,omitempty"`
}

// messageRefFields returns the template's message-ref parameters in
// declaration order.
func messageRefFields(t *Template) []FieldSpec {
	var refs []FieldSpec
	for _, f := range t.Fields() {
		if f.MessageRef {
			refs = append(refs, f)
		}
	}
	return refs
}

// fetchMessageRegistry builds a client for opts and fetches the export
// document. It runs only when the template declares a message-ref
// parameter — templates without one never touch the network for this.
func fetchMessageRegistry(ctx context.Context, opts CreateOptions) (*xregistry.Export, error) {
	if opts.RegistryURL == "" {
		return nil, errors.New("template declares a message registry reference but no registry is configured\npass --registry-url, set INTROPY_REGISTRY_URL, or add registryUrl to the config file")
	}
	client, err := xregistry.NewClient(opts.RegistryURL, xregistry.WithUserAgent(opts.UserAgent))
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve message reference: %w", err)
	}
	return doc, nil
}

// messageRefPrompter wraps the create prompter so a message-ref parameter
// prompts with the registry's message ids as its pick list. The prompt is
// still a plain string prompt — the suggestion list is all the registry
// contributes at this stage; validation and expansion happen after
// resolution, in resolveMessageRefs.
type messageRefPrompter struct {
	next       Prompter
	messageIDs []string
}

func (p messageRefPrompter) Prompt(f FieldSpec) (any, bool, error) {
	if f.MessageRef {
		f.Suggestions = p.messageIDs
	}
	return p.next.Prompt(f)
}

// messageIDs lists every message id in the export, sorted, for the
// message-ref prompt's pick list.
func messageIDs(doc *xregistry.Export) []string {
	var ids []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	return ids
}

// resolveMessageRefs validates each message-ref parameter's value against
// the registry and expands it into the wiring values the skeleton renders:
// the producing endpoint's channel becomes topic and pubsub, and an unset
// contract gets a suggestion derived from the payload schema's id. The
// returned records describe what was resolved, for the scaffold record.
//
// Explicit values win or conflict, never silently override: a topic or
// pubsub already in the values that matches the registry is accepted, and
// one that disagrees is an error naming both. The contract is different —
// it is developer-owned (the registry names a schema document, not a type),
// so a present contract always stands and the registry only fills a gap,
// noted on stderr so the value never lands invisibly.
func resolveMessageRefs(t *Template, values map[string]any, doc *xregistry.Export, notes io.Writer) ([]SubscriptionRecord, error) {
	var subs []SubscriptionRecord
	for _, f := range messageRefFields(t) {
		raw, ok := values[f.Name]
		if !ok {
			// Optional and unanswered: no subscription to record.
			continue
		}
		ref, ok := raw.(string)
		if !ok || ref == "" {
			return nil, fmt.Errorf("parameter %q must be a message id or xid (string), got %v", f.Name, raw)
		}
		sub, err := resolveMessageRef(f.Name, ref, values, doc, notes)
		if err != nil {
			return nil, err
		}
		subs = append(subs, sub)
	}
	return subs, nil
}

func resolveMessageRef(param, ref string, values map[string]any, doc *xregistry.Export, notes io.Writer) (SubscriptionRecord, error) {
	r, err := doc.ResolveMessage(ref)
	var nf *xregistry.MessageNotFoundError
	if errors.As(err, &nf) {
		return SubscriptionRecord{}, fmt.Errorf("%w\n%s", err, knownMessagesMessage(ref, doc))
	}
	if err != nil {
		// An ambiguous bare id already carries its remediation.
		return SubscriptionRecord{}, err
	}

	producers := doc.ProducerEndpointsFor(r.Group.MessageGroupID)
	if len(producers) == 0 {
		return SubscriptionRecord{}, fmt.Errorf("message %s has no producer endpoint declared in the registry\ndeclare a producer endpoint for %s before scaffolding a subscriber", r.Message.Xid, r.Group.MessageGroupID)
	}
	// Several producers publish the same group's messages on their own
	// channels; the sorted-first one is the deterministic pick until the
	// registry grows a way to declare the canonical channel.
	pubsub, topic, err := xregistry.SplitChannel(producers[0].Channel)
	if err != nil {
		return SubscriptionRecord{}, fmt.Errorf("producer endpoint %s: %w", producers[0].EndpointID, err)
	}
	if err := injectWiringValue(values, KeyTopic, topic, r.Message.Xid); err != nil {
		return SubscriptionRecord{}, err
	}
	if err := injectWiringValue(values, KeyPubsub, pubsub, r.Message.Xid); err != nil {
		return SubscriptionRecord{}, err
	}

	sub := SubscriptionRecord{Parameter: param, Message: r.Message.Xid}
	if v := r.Version; v != nil && v.DataschemaXid != "" {
		if s, serr := doc.ResolveSchema(v.DataschemaXid); serr == nil {
			sub.SchemaID = s.Schema.SchemaID
			if s.Version != nil {
				sub.SchemaVersion = s.Version.VersionID
			}
			suggestContract(values, s.Schema.SchemaID, notes)
		}
	}
	return sub, nil
}

// injectWiringValue sets a wiring value from the registry, accepting an
// identical value already present and refusing a conflicting one — the
// registry is the source of truth for where a message flows, and a silent
// override in either direction would hide a real disagreement.
func injectWiringValue(values map[string]any, key, want, messageXid string) error {
	existing, ok := values[key]
	if !ok || existing == nil || existing == "" {
		values[key] = want
		return nil
	}
	if s, _ := existing.(string); s == want {
		return nil
	}
	return fmt.Errorf("%s: the registry declares %q for %s, but the values set %q\nchange --set %s= to match the registry, or fix the registry's channel", key, want, messageXid, existing, key)
}

// suggestContract fills an unset contract parameter with a name derived
// from the schema id. The registry names a schema document, not a type, so
// this is a suggestion — a contract the developer already set always
// stands, and the fill is noted so it never lands invisibly.
func suggestContract(values map[string]any, schemaID string, notes io.Writer) {
	if existing, ok := values[KeyContract]; ok && existing != nil && existing != "" {
		return
	}
	suggestion := SuggestContractName(schemaID)
	if suggestion == "" {
		return
	}
	values[KeyContract] = suggestion
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (suggested from the message schema; override with --set %s=<value>)\n", KeyContract, suggestion, KeyContract)
	}
}

// SuggestContractName derives a type name from a schema id: the version
// suffix is stripped and the kebab-case remainder is Pascal-cased
// ("product-export.v1" → "ProductExport"). It is a prompt-time suggestion,
// not a guarantee — no type by this name exists until it is written or
// generated, which is why the developer can always override it.
func SuggestContractName(schemaID string) string {
	base := schemaID
	if i := strings.LastIndex(base, ".v"); i > 0 && allDigits(base[i+2:]) {
		base = base[:i]
	}
	var b strings.Builder
	for _, part := range strings.Split(base, "-") {
		if part == "" {
			continue
		}
		b.WriteString(strings.ToUpper(part[:1]))
		b.WriteString(part[1:])
	}
	return b.String()
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// knownMessagesMessage builds the remediation line for an unknown message
// reference: close matches when the ref narrows the list, the full catalog
// when it does not. The registry is small enough that listing it is help,
// not noise.
func knownMessagesMessage(ref string, doc *xregistry.Export) string {
	ids := messageIDs(doc)
	var close []string
	for _, id := range ids {
		if strings.Contains(id, ref) {
			close = append(close, id)
		}
	}
	if len(close) > 0 {
		return "close matches: " + strings.Join(close, ", ")
	}
	if len(ids) > 0 {
		return "known messages: " + strings.Join(ids, ", ")
	}
	return "the registry declares no messages"
}

