package template

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const subscriberTemplateYAML = `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: subscriber
spec:
  parameters:
    type: object
    required: [name, subscription]
    properties:
      name:
        type: string
      subscription:
        type: string
        title: Message
        x-intropy-message-ref: true
      topic:
        type: string
      pubsub:
        type: string
      contract:
        type: string
`

// messageRegistryFixture is the export document the test registry serves:
// one message with a producer and a schema, one message id shared across
// two groups for ambiguity tests, one group with no producer.
const messageRegistryFixture = `{
  "registryid": "intropy",
  "messagegroups": {
    "io.intropy.maxbo.product": {
      "messagegroupid": "io.intropy.maxbo.product",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "dataschemaxid": "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1"
            }
          }
        }
      }
    },
    "io.intropy.acme.orders": {
      "messagegroupid": "io.intropy.acme.orders",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.acme.orders/messages/io.intropy.maxbo.product.export",
          "versions": {
            "1": {"versionid": "1", "isdefault": true}
          }
        },
        "io.intropy.acme.orders.placed": {
          "messageid": "io.intropy.acme.orders.placed",
          "xid": "/messagegroups/io.intropy.acme.orders/messages/io.intropy.acme.orders.placed",
          "versions": {
            "1": {"versionid": "1", "isdefault": true}
          }
        }
      }
    }
  },
  "schemagroups": {
    "io.intropy.maxbo.product": {
      "schemagroupid": "io.intropy.maxbo.product",
      "schemas": {
        "product-export.v1": {
          "schemaid": "product-export.v1",
          "versions": {
            "1": {"versionid": "1", "isdefault": true, "format": "JsonSchema/draft/2020-12"}
          }
        }
      }
    }
  },
  "endpoints": {
    "perfion-extractor": {
      "endpointid": "perfion-extractor",
      "usage": ["producer"],
      "channel": "product-distribution-pubsub/sbt-test-product-extractor-001",
      "messagegroups": ["/messagegroups/io.intropy.maxbo.product"]
    }
  }
}`

func newSubscriberLibrary(t *testing.T, tag string) *testLibrary {
	t.Helper()
	return newTestLibrary(t, tag, map[string]string{
		"subscriber/template.yaml":           subscriberTemplateYAML,
		"subscriber/skeleton/wiring.txt.tmpl": "topic={{ .topic }} pubsub={{ .pubsub }} contract={{ .contract }}\n",
	})
}

func messageRegistryServer(t *testing.T) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(messageRegistryFixture))
	}))
	t.Cleanup(srv.Close)
	return srv
}

func readScaffoldT(t *testing.T, dir string) Scaffold {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, ScaffoldRelPath))
	if err != nil {
		t.Fatal(err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		t.Fatal(err)
	}
	return s
}

func TestCreateResolvesMessageRef(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)
	outDir := filepath.Join(t.TempDir(), "out")
	var stderr bytes.Buffer

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   outDir,
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "io.intropy.maxbo.product.export"},
		NoInput:     true,
		Stderr:      &stderr,
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err != nil {
		t.Fatalf("Create: %v\nstderr: %s", err, stderr.String())
	}

	rendered, err := os.ReadFile(filepath.Join(outDir, "wiring.txt"))
	if err != nil {
		t.Fatal(err)
	}
	want := "topic=sbt-test-product-extractor-001 pubsub=product-distribution-pubsub contract=ProductExport"
	if !strings.Contains(string(rendered), want) {
		t.Errorf("rendered wiring = %q, want it to contain %q", rendered, want)
	}

	scaffold := readScaffoldT(t, outDir)
	if len(scaffold.Subscriptions) != 1 {
		t.Fatalf("subscriptions = %+v", scaffold.Subscriptions)
	}
	sub := scaffold.Subscriptions[0]
	if sub.Parameter != "subscription" {
		t.Errorf("parameter = %q", sub.Parameter)
	}
	if sub.Message != "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export" {
		t.Errorf("message = %q", sub.Message)
	}
	if sub.SchemaID != "product-export.v1" || sub.SchemaVersion != "1" {
		t.Errorf("schema = %q @ %q", sub.SchemaID, sub.SchemaVersion)
	}
	// The resolved values are what system assembly later reads back.
	if got := scaffold.Values["topic"]; got != "sbt-test-product-extractor-001" {
		t.Errorf("scaffold topic = %v", got)
	}

	// The contract suggestion is noted, never invisible.
	if !strings.Contains(stderr.String(), "contract: ProductExport") {
		t.Errorf("stderr should note the contract suggestion, got %q", stderr.String())
	}
}

func TestCreateMessageRefAcceptsMatchingExplicitTopic(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:  "subscriber",
		OutputDir: filepath.Join(t.TempDir(), "out"),
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "loader",
			"subscription": "io.intropy.maxbo.product.export",
			"topic":        "sbt-test-product-extractor-001",
		},
		NoInput:     true,
		Stderr:      &bytes.Buffer{},
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err != nil {
		t.Fatalf("matching explicit topic should be accepted: %v", err)
	}
}

func TestCreateMessageRefRejectsConflictingTopic(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:  "subscriber",
		OutputDir: filepath.Join(t.TempDir(), "out"),
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "loader",
			"subscription": "io.intropy.maxbo.product.export",
			"topic":        "some-other-topic",
		},
		NoInput:     true,
		Stderr:      &bytes.Buffer{},
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err == nil {
		t.Fatal("expected a conflict error")
	}
	for _, want := range []string{"sbt-test-product-extractor-001", "some-other-topic", "--set topic="} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error should name %q: %q", want, err)
		}
	}
}

func TestCreateMessageRefUnknownMessage(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   filepath.Join(t.TempDir(), "out"),
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "orders.placed"},
		NoInput:     true,
		Stderr:      &bytes.Buffer{},
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err == nil {
		t.Fatal("expected an unknown-message error")
	}
	if !strings.Contains(err.Error(), "close matches: io.intropy.acme.orders.placed") {
		t.Errorf("error should list close matches, got %q", err)
	}
}

func TestCreateMessageRefAmbiguousMessage(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   filepath.Join(t.TempDir(), "out"),
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "io.intropy.maxbo.product.export"},
		NoInput:     true,
		Stderr:      &bytes.Buffer{},
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	// The fixture declares the id in two groups; the bare id is ambiguous
	// even though one of them has a producer.
	if err == nil || !strings.Contains(err.Error(), "matches multiple messages") {
		t.Fatalf("expected an ambiguity error, got %v", err)
	}
}

func TestCreateMessageRefByXid(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
