func TestCreateMessageRefRegistryUnreachable(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	outDir := filepath.Join(t.TempDir(), "out")

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
